/*
 * GLOBAL CONSTANT: CLOSE_DELTA
 *
 *   Margin of error for float comparisons.
 */
static const SE_FLOAT64 CLOSE_DELTA = 0.0005;

/*
 * GLOBAL VARIABLE: _ErrHasBeenSet
 *
 *   Whether error file pointer has been set by the user. If
 *   SE_FALSE, use stderr.
 */
static SE_BOOLEAN _ErrHasBeenSet = SE_FALSE;

/*
 * GLOBAL VARIABLE: conv_err_file_ptr
 *
 *   The error file pointer. If this has not been set, use
 *   stderr.
 */
static FILE *conv_err_file_ptr;


/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_SetErrorFilePtr
 *
 *-----------------------------------------------------------------------------
 */
SE_COORD_STATUS_CODE_ENUM
SE_SetErrorFilePtr
(
    FILE *err_file_ptr
)
{
    SE_COORD_STATUS_CODE_ENUM status;

    if (err_file_ptr)
    {
        conv_err_file_ptr = err_file_ptr;
        _ErrHasBeenSet    = SE_TRUE;
        status = SE_COORD_SUCCESS;
    }
    else
    {
        status = SE_COORD_FAILURE;
        conv_err_file_ptr = stderr;
    }
    return status;
} /* end SE_SetErrorFilePtr */


/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_GetErrorFilePtr
 *
 *-----------------------------------------------------------------------------
 */
FILE *
SE_GetErrorFilePtr(void)
{
    if (_ErrHasBeenSet)
        return conv_err_file_ptr;
    else
        return stderr;
} /* end SE_GetErrorFilePtr */


/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_ValidCMYData
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SE_ValidCMYData
(
    const SE_CMY_DATA *value_ptr,
          SE_BOOLEAN   print_error,
          SE_UINT32   *error_count_ptr
)
{
    SE_BOOLEAN  result = SE_TRUE;
    FILE       *f_ptr = NULL;

    if (print_error)
        f_ptr = SE_GetErrorFilePtr();

    if (!value_ptr)
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
        {
            fprintf(f_ptr, "SE_ValidCMYData: NULL value_ptr\n");
        }
        return result;
    }

    if ((value_ptr->cyan < 0.0) || (value_ptr->cyan > 1.0))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal cyan value (%s)\n",
                    SE_PrintFloat64(value_ptr->cyan));
    }

    if ((value_ptr->magenta < 0.0) || (value_ptr->magenta > 1.0))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal magenta value (%s)\n",
                    SE_PrintFloat64(value_ptr->magenta));
    }

    if ((value_ptr->yellow < 0.0) || (value_ptr->yellow > 1.0))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal yellow value (%s)\n",
                    SE_PrintFloat64(value_ptr->yellow));
    }
    return result;
} /* end SE_ValidCMYData */


