/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SRM_ValidGM3DParameters
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SRM_ValidGM3DParameters
(
    const SRM_GM_3D_PARAMETERS *value_ptr,
          SE_BOOLEAN            print_error,
          SE_UINT32            *error_count_ptr
)
{
    SE_BOOLEAN  result = SE_TRUE;
    FILE       *f_ptr = NULL;

    if (print_error)
        f_ptr = SE_GetErrorFilePtr();

    if (!value_ptr)
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
        {
            fprintf(f_ptr, "SRM_ValidGM3DParameters: NULL value_ptr\n");
        }
        return result;
    }

    if ((value_ptr->gm_epoch < 1945.0) || (value_ptr->gm_epoch > 2000.0))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal gm_epoch value (%s)\n",
                    SE_PrintFloat64(value_ptr->gm_epoch));
    }

    if ((value_ptr->gm_earth_radius < 6000000.0) ||
        (value_ptr->gm_earth_radius > 6600000.0))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal gm_earth_radius value (%s)\n",
                    SE_PrintFloat64(value_ptr->gm_earth_radius));
    }
    return result;
} /* end SRM_ValidGM3DParameters */


