/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_ValidColorData
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SE_ValidColorData
(
    const SE_COLOR_DATA *value_ptr,
          SE_BOOLEAN     print_error,
          SE_UINT32     *error_count_ptr
)
{
    SE_BOOLEAN  result = SE_TRUE;
    FILE       *f_ptr = NULL;

    if (print_error)
        f_ptr = SE_GetErrorFilePtr();

    if (!value_ptr)
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
        {
            fprintf(f_ptr, "SE_ValidColorData: NULL value_ptr\n");
        }
        return result;
    }

    switch (value_ptr->color_model)
    {
        case SE_RGB_MODEL:
            if (!SE_ValidRGBData(&(value_ptr->u.rgb), print_error,
                      error_count_ptr))
            {
                result = SE_FALSE;
                if (print_error)
                    fprintf(f_ptr, "Illegal SE_RGB_DATA value\n");
            }
            break;

        case SE_CMY_MODEL:
            if (!SE_ValidCMYData(&(value_ptr->u.cmy), print_error,
                      error_count_ptr))
            {
                result = SE_FALSE;
                if (print_error)
                    fprintf(f_ptr, "Illegal SE_CMY_DATA value\n");
            }
            break;

        case SE_HSV_MODEL:
            if (!SE_ValidHSVData(&(value_ptr->u.hsv), print_error,
                      error_count_ptr))
            {
                result = SE_FALSE;
                if (print_error)
                    fprintf(f_ptr, "Illegal SE_HSV_DATA value\n");
            }
            break;

        default:
             result = SE_FALSE;
             if (error_count_ptr) (*error_count_ptr)++;
             if (print_error)
                 fprintf(f_ptr, "Illegal SE_COLOR_MODEL_ENUM value (%d)\n",
                         (int) value_ptr->color_model);
             break;
    } /* end switch */
    return result;
} /* end SE_ValidColorData */


/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_ValidColorModel
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SE_ValidColorModel
(
    SE_COLOR_MODEL_ENUM value
)
{
    SE_BOOLEAN result = SE_TRUE;

    switch (value)
    {
        case SE_RGB_MODEL:
        case SE_CMY_MODEL:
        case SE_HSV_MODEL:
            break;

        default:
            result = SE_FALSE;
            break;
    } /* end switch */
    return result;
} /* end SE_ValidColorModel */


/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_ValidColorStatusCode
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SE_ValidColorStatusCode
(
    SE_COLOR_STATUS_CODE_ENUM value
)
{
    SE_BOOLEAN result = SE_TRUE;

    switch (value)
    {
        case SE_COLOR_SUCCESS:
        case SE_COLOR_NULL_PTR_OUT_PARAMETER:
        case SE_COLOR_INVALID_ORIGINAL_COLOR:
        case SE_COLOR_INVALID_NEW_COLOR_MODEL:
            break;

        default:
            result = SE_FALSE;
            break;
    } /* end switch */
    return result;
} /* end SE_ValidColorStatusCode */


/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_ValidCoord
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SE_ValidCoord
(
    const SE_COORD *value_ptr,
          SE_BOOLEAN  print_error,
          SE_UINT32 *error_count_ptr
)
{
    SE_BOOLEAN  result = SE_TRUE;
    FILE       *f_ptr = NULL;

    if (print_error)
        f_ptr = SE_GetErrorFilePtr();

    if (!value_ptr)
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
        {
            fprintf(f_ptr, "SE_ValidCoord: NULL value_ptr\n");
        }
        return result;
    }

    switch (value_ptr->is_2D)
    {
        case SE_FALSE:
            if (!SE_ValidCoord3D(&(value_ptr->u.coord_3d), print_error,
                      error_count_ptr))
            {
                result = SE_FALSE;
                if (print_error)
                    fprintf(f_ptr, "Illegal SE_COORD_3D value\n");
            }
            break;

        case SE_TRUE:
            if (!SE_ValidCoord2D(&(value_ptr->u.coord_2d), print_error,
                      error_count_ptr))
            {
                result = SE_FALSE;
                if (print_error)
                    fprintf(f_ptr, "Illegal SE_COORD_2D value\n");
            }
            break;

        default:
             result = SE_FALSE;
             if (error_count_ptr) (*error_count_ptr)++;
             if (print_error)
                 fprintf(f_ptr, "Illegal SE_BOOLEAN value (%d)\n", (int)
                         value_ptr->is_2D);
             break;
    } /* end switch */
    return result;
} /* end SE_ValidCoord */


/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SE_ValidCoord2D
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SE_ValidCoord2D
(
    const SE_COORD_2D *value_ptr,
          SE_BOOLEAN   print_error,
          SE_UINT32   *error_count_ptr
)
{
    SE_BOOLEAN  result = SE_TRUE;
    FILE       *f_ptr = NULL;

    if (print_error)
        f_ptr = SE_GetErrorFilePtr();

    if (!value_ptr)
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
        {
            fprintf(f_ptr, "SE_ValidCoord2D: NULL value_ptr\n");
        }
        return result;
    }

    switch (value_ptr->spatial_reference_frame)
    {
        case SRM_GD_2D_SRF:
            if (!SRM_ValidGD2DCoord(&(value_ptr->u.gd_coord), print_error,
                      error_count_ptr))
            {
                result = SE_FALSE;
                if (print_error)
                    fprintf(f_ptr, "Illegal SRM_GD_2D_COORD value\n");
            }
            break;

        case SRM_EC_2D_SRF:
            break;

        case SRM_PS_2D_SRF:
            break;

        case SRM_LCC_2D_SRF:
            break;

        case SRM_TM_2D_SRF:
            break;

        case SRM_UTM_2D_SRF:
            if (!SRM_ValidUTM2DCoord(&(value_ptr->u.utm_coord), print_error,
                      error_count_ptr))
            {
                result = SE_FALSE;
                if (print_error)
                    fprintf(f_ptr, "Illegal SRM_UTM_2D_COORD value\n");
            }
            break;

        case SRM_LTP_2D_SRF:
            break;

        case SRM_LSR_2D_SRF:
            break;

        case SRM_M_2D_SRF:
            break;

        case SRM_OM_2D_SRF:
            break;

        case SRM_UPS_2D_SRF:
            break;

        default:
             result = SE_FALSE;
             if (error_count_ptr) (*error_count_ptr)++;
             if (print_error)
                 fprintf(f_ptr, "Illegal SRM_SRF_2D_ENUM value (%d)\n", (int)
                         value_ptr->spatial_reference_frame);
             break;
    } /* end switch */
    return result;
} /* end SE_ValidCoord2D */


