/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SRM_ValidEC2DParameters
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SRM_ValidEC2DParameters
(
    const SRM_EC_2D_PARAMETERS *value_ptr,
          SE_BOOLEAN            print_error,
          SE_UINT32            *error_count_ptr
)
{
    SE_BOOLEAN  result = SE_TRUE;
    FILE       *f_ptr = NULL;

    if (print_error)
        f_ptr = SE_GetErrorFilePtr();

    if (!value_ptr)
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
        {
            fprintf(f_ptr, "SRM_ValidEC2DParameters: NULL value_ptr\n");
        }
        return result;
    }

    if (!SE_ValidHorizontalDatum(value_ptr->horizontal_datum))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal SE_HORIZONTAL_DATUM_ENUM value (%d)\n",
                (int) value_ptr->horizontal_datum);
    }
    else if ((value_ptr->horizontal_datum != SE_SPHERICAL_ACM_HDATUM) &&
             (value_ptr->horizontal_datum != SE_SPHERICAL_COA_HDATUM) &&
             (value_ptr->horizontal_datum != SE_SPHERICAL_NOG_HDATUM) &&
             (value_ptr->horizontal_datum != SE_SPHERICAL_MFE_HDATUM) &&
             (value_ptr->horizontal_datum != SE_SPHERICAL_MOD_M_HDATUM) &&
             (value_ptr->horizontal_datum != SE_SPHERICAL_MOD_S_HDATUM) &&
             (value_ptr->horizontal_datum != SE_SPHERICAL_MOD_T_HDATUM) &&
             (value_ptr->horizontal_datum != SE_SPHERICAL_MM5_HDATUM))
    {
       /*
        * NOTE: EC only supports spherical ERM/ORMs; if new spherical models
        *       are added, this check must be updated. -- Dan Toms
        */
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Invalid SE_HORIZONTAL_DATUM_ENUM value (%s)\n"\
                           "   (EC only supports spherical ERM/ORMs)\n",
                    SE_PrintHorizontalDatum(value_ptr->horizontal_datum));
    }
    if ((value_ptr->geodetic_latitude+CLOSE_DELTA < -90.0) ||
        (value_ptr->geodetic_latitude-CLOSE_DELTA > 90.0))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal value_ptr->geodetic_latitude value (%s)\n",
                SE_PrintFloat64(value_ptr->geodetic_latitude));
    }
    if ((value_ptr->geodetic_longitude+CLOSE_DELTA < -180.0) ||
        (value_ptr->geodetic_longitude-CLOSE_DELTA > 180.0))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal value_ptr->geodetic_longitude value"\
                    " (%s)\n", SE_PrintFloat64(value_ptr->geodetic_longitude));
    }
    if ((value_ptr->central_scale_factor+CLOSE_DELTA < 0.8) ||
        (value_ptr->central_scale_factor-CLOSE_DELTA > 1.2))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal value_ptr->central_scale_factor value"\
                    " (%s)\n",
                SE_PrintFloat64(value_ptr->central_scale_factor));
    }
    return result;
} /* end SRM_ValidEC2DParameters */


