/*
 *-----------------------------------------------------------------------------
 *
 * FUNCTION: SRM_ValidLCC2DParameters
 *
 *-----------------------------------------------------------------------------
 */
SE_BOOLEAN
SRM_ValidLCC2DParameters
(
    const SRM_LCC_2D_PARAMETERS *value_ptr,
          SE_BOOLEAN             print_error,
          SE_UINT32             *error_count_ptr
)
{
    SE_BOOLEAN  result = SE_TRUE;
    FILE       *f_ptr = NULL;

    if (print_error)
        f_ptr = SE_GetErrorFilePtr();

    if (!value_ptr)
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
        {
            fprintf(f_ptr, "SRM_ValidLCC2DParameters: NULL value_ptr\n");
        }
        return result;
    }

    if (!SE_ValidHorizontalDatum(value_ptr->horizontal_datum))
    {
        result = SE_FALSE;
        if (error_count_ptr) (*error_count_ptr)++;
        if (print_error)
            fprintf(f_ptr, "Illegal SE_HORIZONTAL_DATUM_ENUM value (%d)\n",
                (int) value_ptr->horizontal_datum);
    }
    if (value_ptr->north_parallel_geodetic_latitude ==
        value_ptr->south_parallel_geodetic_latitude)
    {
        /*
         * Check bounds on Standard Parallel
         */
        if ((fabs(value_ptr->north_parallel_geodetic_latitude) < 1) &&
            (fabs(value_ptr->north_parallel_geodetic_latitude) > 89))
        {
            result = SE_FALSE;
            if (error_count_ptr) (*error_count_ptr)++;
            if (print_error)
                fprintf(f_ptr,
                   "[SEDRIS CONVERSIONS] LCC with one standard parallel "\
                   "Params out of bounds: "\
                   "Standard parallel must be within 1<x<89 "\
                   "degrees.");
        }
    }
    else /* 2 standard parallels */
    {
        if (fabs(value_ptr->north_parallel_geodetic_latitude)<1  ||
            fabs(value_ptr->north_parallel_geodetic_latitude)>89 ||
            fabs(value_ptr->south_parallel_geodetic_latitude)<1  ||
            fabs(value_ptr->south_parallel_geodetic_latitude)>89)
        {
            /*
             * Check bounds on Standard Parallels
             */
            result = SE_FALSE;
            if (error_count_ptr) (*error_count_ptr)++;
            if (print_error)
                fprintf(f_ptr, "[SEDRIS CONVERSIONS] LCC2 Params "\
                    "out of bounds: north, south parallel geodetic latitudes"\
                    "must be within 1<x<89 degrees.");
        }
        if ((value_ptr->north_parallel_geodetic_latitude >1 &&
             value_ptr->south_parallel_geodetic_latitude < 0) ||
            (value_ptr->south_parallel_geodetic_latitude >1 &&
             value_ptr->north_parallel_geodetic_latitude < 0)
           )
        {
            result = SE_FALSE;
            if (error_count_ptr) (*error_count_ptr)++;
            if (print_error)
                fprintf(f_ptr, "[SEDRIS CONVERSIONS] LCC2 Params "\
                    "error: standard parallels must be in same hemisphere.");
        }
    }
    return result;
} /* end SRM_ValidLCC2DParameters */


